<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import PrimaryHeader from '@/components/PrimaryHeader.vue'
import { getBusinessDashboardStatistics, type BusinessDashboardStatistics } from '@/api/business-statistics'
import { useUserStore } from '@/stores/user'

const props = withDefaults(defineProps<{ embedded?: boolean }>(), { embedded: false })
const user = useUserStore()
const active = ref<'overview' | 'tasks' | 'abnormal' | 'scenes'>('overview')
const loading = ref(false)
const error = ref('')
const data = ref<BusinessDashboardStatistics>()
const tabs = [{ key:'overview' as const, label:'数据总览', icon:'▦' }, { key:'tasks' as const, label:'任务统计', icon:'✓' }, { key:'abnormal' as const, label:'异常图斑', icon:'!' }, { key:'scenes' as const, label:'场景成果', icon:'◈' }]
const overview = computed(() => data.value?.overview)
const total = computed(() => Math.max(overview.value?.taskCount || 0, 1))
const maxScene = computed(() => Math.max(...(data.value?.sceneStats.map(item => item.taskCount) || [1]), 1))
const taskBars = computed(() => data.value ? [{ label:'待执行', value:data.value.taskSummary.pending, color:'#38c8ff' }, { label:'执行中', value:data.value.taskSummary.executing, color:'#54e1b8' }, { label:'待核查', value:data.value.taskSummary.pendingVerify, color:'#ffbe58' }, { label:'已完成', value:data.value.taskSummary.finished, color:'#7e92ff' }] : [])
async function load() { loading.value = true; error.value = ''; try { data.value = await getBusinessDashboardStatistics({ deptId: user.activeDeptId || user.organizationId, days: 30 }) } catch (e) { error.value = e instanceof Error ? e.message : '统计数据加载失败' } finally { loading.value = false } }
onMounted(() => void load())
</script>
<template>
  <div class="results-page" :class="{ embedded: props.embedded }"><PrimaryHeader v-if="!props.embedded" /><main><aside><b>数据管理</b><button v-for="tab in tabs" :key="tab.key" :class="{ active:active === tab.key }" @click="active = tab.key"><i>{{ tab.icon }}</i>{{ tab.label }}</button></aside><section class="results-content"><header><div><b>{{ tabs.find(item => item.key === active)?.label }}</b><span>当前单位：{{ user.organization.name }}</span></div><button @click="load">刷新数据</button></header><p v-if="error" class="error">{{ error }}</p><div v-else-if="loading" class="state">正在加载后端统计数据…</div><template v-else-if="data && overview"><section class="metrics"><article><span>任务总数</span><b>{{ overview.taskCount }}</b><small>覆盖 {{ overview.sceneCount }} 个业务场景</small></article><article><span>异常图斑</span><b>{{ overview.abnormalCount }}</b><small>待核查 {{ overview.abnormalPendingCount }} 个</small></article><article><span>异常面积</span><b>{{ overview.abnormalArea.toLocaleString() }}</b><small>平方米</small></article><article><span>成果批次</span><b>{{ overview.resultCount }}</b><small>范围要素 {{ overview.geometryCount }} 个</small></article></section><section v-if="active === 'overview'" class="grid overview"><article class="panel trend"><h2>近 30 日任务与异常趋势</h2><div class="trend-bars"><i v-for="item in data.trend.items" :key="item.date" :style="{ height: `${Math.max(8, item.abnormalCount / Math.max(...data.trend.items.map(row => row.abnormalCount), 1) * 100)}%` }"><small>{{ item.abnormalCount }}</small><em>{{ item.date.slice(5) }}</em></i></div></article><article class="panel"><h2>异常类型分布</h2><div class="list"><div v-for="item in data.abnormalSummary.typeCounts" :key="item.key"><span>{{ item.name }}</span><b>{{ item.count }}</b><i :style="{ width: `${item.count / Math.max(overview.abnormalCount,1) * 100}%` }"></i></div></div></article></section><section v-else-if="active === 'tasks'" class="grid"><article class="panel wide"><h2>任务状态统计</h2><div class="status-bars"><div v-for="item in taskBars" :key="item.label"><i :style="{ height: `${item.value / total * 100}%`, background:item.color }"></i><b>{{ item.value }}</b><span>{{ item.label }}</span></div></div></article></section><section v-else-if="active === 'abnormal'" class="grid"><article class="panel wide"><h2>图斑处置状态</h2><div class="list"><div v-for="item in data.abnormalSummary.handleStatusCounts" :key="item.key"><span>{{ item.name }}</span><b>{{ item.count }}</b><i :style="{ width: `${item.count / Math.max(overview.abnormalCount,1) * 100}%` }"></i></div></div></article></section><section v-else class="grid"><article class="panel wide"><h2>场景业务成果</h2><div class="scene-table"><div class="head"><span>业务场景</span><span>任务</span><span>异常图斑</span><span>成果批次</span></div><div v-for="item in data.sceneStats" :key="item.sceneId"><span><b>{{ item.sceneName }}</b><i><em :style="{ width:`${item.taskCount / maxScene * 100}%` }"></em></i></span><span>{{ item.taskCount }}</span><span>{{ item.abnormalCount }}</span><span>{{ item.resultCount }}</span></div></div></article></section></template></section></main></div>
</template>
<style scoped lang="scss">
