-gradient(#48e1e5,#1a78c8);border-radius:3px 3px 0 0}.trend-bars small{position:absolute;top:-18px;left:50%;color:#93edff;font-size:10px;transform:translateX(-50%)}.trend-bars em{position:absolute;bottom:-24px;left:50%;color:#799db8;font-size:10px;font-style:normal;white-space:nowrap;transform:translateX(-50%)}.list>div{position:relative;display:grid;grid-template-columns:1fr auto;gap:10px;padding:11px 0;border-bottom:1px solid #16476d}.list span{z-index:1}.list b{z-index:1;color:#76e8ff}.list i{position:absolute;left:0;bottom:0;height:3px;background:#45cafa}.status-bars{justify-content:space-around;gap:32px}.status-bars div{height:100%;flex:1;display:grid;grid-template-rows:1fr auto auto;justify-items:center}.status-bars i{align-self:end;width:min(56px,75%);border-radius:5px 5px 0 0}.status-bars b{padding-top:6px;color:#dffaff}.status-bars span{color:#82a9c4;font-size:13px}.scene-table>.head,.scene-table>div{display:grid;grid-template-columns:2fr repeat(3,1fr);align-items:center;gap:8px;padding:11px;border-bottom:1px solid #17466d}.scene-table>.head{color:#8bc4eb;background:#0a416c}.scene-table b{display:block}.scene-table i{display:block;height:4px;margin-top:6px;background:#113a5c}.scene-table em{display:block;height:100%;background:#55d5e9}.state,.error{display:grid;min-height:300px;place-items:center}.error{color:#ffa9a9}@media(max-width:1100px){.results-page main{grid-template-columns:145px minmax(0,1fr)}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.results-content{padding:10px}.grid{grid-template-columns:1fr}.results-page aside{padding-inline:7px}}
</style>
